def level2_router(llm, email):
    label = llm(f'Classify as refund, complaint or query: {email}')
    return {'refund': 'refund_queue', 'complaint': 'escalations'}.get(label, 'faq_bot')

def level3_agent(llm, tools, goal, max_steps=8):
    history = [goal]
    for _ in range(max_steps):
        decision = llm(history)                      # model chooses the next action
        if decision['action'] == 'finish':
            return decision['answer']
        result = tools[decision['action']](**decision['args'])
        history.append(result)                       # feedback shapes the next choice
    return 'stopped: step limit reached'

