LABELS = {0: 'fixed code', 1: 'LLM call', 2: 'LLM router', 3: 'agent'}

n = int(input())
agents = 0
for _ in range(n):
    parts = input().split()
    name = parts[0]
    flags = {}
    for item in parts[1:]:
        key, _, value = item.partition('=')
        flags[key.lower()] = value.strip().lower() == 'yes'
    if not flags.get('llm'):
        level = 0
    elif flags.get('loop'):
        level = 3
    elif flags.get('tools') or flags.get('route'):
        level = 2
    else:
        level = 1
    if level == 3:
        agents += 1
    print(f'{name}: level {level} ({LABELS[level]})')
print(f'Agents: {agents}/{n}')
